export const ATLAS_BLOCK_START =
  '<!-- vulcan:atlas:start - generated by vulcan sync from .configs/vulcan.config.*; do not edit -->';
export const ATLAS_BLOCK_END = '<!-- vulcan:atlas:end -->';
const START_PREFIX = '<!-- vulcan:atlas:start';
const MUST_READ = '## Must read first';

/**
 * The guidance every agent that reads AGENTS.md gets, whatever its client drops of the MCP server's
 * own text. Rendered from the config, so it is the same for every developer and safe to commit.
 */
export const renderAtlasBlock = (opts: { project: string; sources: string[] }): string =>
  [
    ATLAS_BLOCK_START,
    '## Atlas',
    '',
    `The \`atlas\` MCP server holds the real code and docs of: ${[`${opts.project} (this repository)`, ...opts.sources].join(', ')}.`,
    'Look facts up there before you answer or write from memory (V-P-07):',
    '`symbol` before you use an export (signature, import path, source line); `search`, then `get`, for how something works or which convention applies; `version` or `changes` for a release or an upgrade.',
    'A new app or package: ask `presets` which preset and which `vulcan add` command, run it, and never hand-write package.json, tsconfig or scripts.',
    'How to build something here (a feature, a controller, a service, a repository): `search` first, then `get`, before you answer; a plan never says "check atlas" for a step you have not done.',
    'To build a feature, or to answer how one would be built, load the `build-a-feature` skill first.',
    ATLAS_BLOCK_END,
    '',
  ].join('\n');

/**
 * Puts the block into AGENTS.md: rewritten between its markers when it is there, else inserted
 * before the section that follows "Must read first", else appended. Text outside is never touched.
 */
export const mergeAtlasBlock = (opts: {
  text: string;
  block: string;
}): { changed: boolean; text: string } => {
  const start = opts.text.indexOf(START_PREFIX);
  const end = opts.text.indexOf(ATLAS_BLOCK_END);
  let text: string;

  if (opts.text === '') {
    text = opts.block;
  } else if (start !== -1 && end > start) {
    text = `${opts.text.slice(0, start)}${opts.block.trimEnd()}${opts.text.slice(end + ATLAS_BLOCK_END.length)}`;
  } else {
    const heading = opts.text.indexOf(MUST_READ);
    const next = heading === -1 ? -1 : opts.text.indexOf('\n## ', heading + MUST_READ.length);

    if (next === -1) {
      text = `${opts.text}${opts.text.endsWith('\n') ? '' : '\n'}\n${opts.block}`;
    } else {
      const at = next + 1;

      text = `${opts.text.slice(0, at)}${opts.block}\n${opts.text.slice(at)}`;
    }
  }

  return { changed: text !== opts.text, text };
};
